export const NerLabel = z.enum(["PERSON","ORG","GPE","LOC","PRODUCT","EVENT","LANGUAGE","MONEY","METRIC","STOCK_TICKER","WEBSITE"]);
export type NerLabel = z.infer<typeof NerLabel>;

export const OutputSettings = z.object({ "image_dark_mode": z.union([z.boolean(), z.null()]).describe("Whether to render card preview images in dark mode.").optional(), "force_refresh": z.boolean().describe("Instant mode only. When false (default), instant returns existing cached embeds as-is (fastest) and never writes. When true, instant retrieves data for embeds that are missing or stale, then creates or refreshes their static embeds — slower for those, but it writes the result. Embeds already fresh (within the refresh cadence) are still served as-is, not re-retrieved or updated.").default(false) }).strict();
export type OutputSettings = z.infer<typeof OutputSettings>;

export const ReasoningEvent = z.object({ "kind": z.literal("reasoning").default("reasoning"), "id": z.string(), "delta": z.string(), "done": z.boolean().default(false) });
export type ReasoningEvent = z.infer<typeof ReasoningEvent>;

export const RelationKind = z.enum(["related","data","sibling","membership"]).describe("How a relation group was derived. The SOURCE kind is Tako-internal only\nand intentionally absent from this public twin.");
export type RelationKind = z.infer<typeof RelationKind>;

export const ResultContent = z.object({ "content_format": z.union([z.lazy(() => ContentsFormat), z.null()]).optional(), "cost": z.number().default(0), "data": z.union([z.string(), z.null()]).optional(), "records": z.union([z.array(z.record(z.string(), z.union([z.string(), z.number(), z.number().int(), z.boolean(), z.null()]))), z.null()]).optional(), "dataset": z.union([z.lazy(() => TakoDataset), z.null()]).optional(), "url": z.union([z.string(), z.null()]).optional(), "expires_at": z.union([z.string(), z.null()]).optional(), "total_rows": z.union([z.number().int(), z.null()]).optional(), "truncated": z.boolean().default(false), "export_pricing": z.union([z.lazy(() => ExportPricing), z.null()]).optional() }).describe("Describes the downloadable content behind a result. For a Tako card CSV\nexport the charge is a flat per-export baseline plus a per-source per-row CPM\non the rows returned (beyond the free-row allowance); web text is the canonical\nContents rate. On `/contents` responses `cost` is the ACTUAL charge and still\nreconciles with what that response billed — EXCEPT a `quote_only` response,\nwhere `cost` is a prospective price (the export was neither fetched nor billed;\npayload/url are null). On search/answer downloadable cards\n`cost` is a PROSPECTIVE `/contents` quote (the per-export baseline floor), NOT\nwhat this response billed — so on a metered `include_contents` request the\nper-card `cost` diverges from `usage.total_cost_usd` (the inline preview bills\n≈$0) and summing per-card `cost` will not reconcile with `usage`; treat `cost`\n+`export_pricing` as \"what a `/contents` export of this card would cost.\"\n`export_pricing` carries the rate so a caller can compute the full charge\nbefore fetching: baseline_usd + row_cpm_usd * max(0, rows - free_rows) / 1000\n(rows <= max_rows_ceiling). `export_pricing` is null for web text and\nnon-downloadable content. Exactly\none payload group is populated once\ncontents are delivered: `data` (CSV/web text), `records` (verbose JSON),\n`dataset` (compact TakoDataset), or `url`+`expires_at` (presigned download);\n`content_format` names the serialization (null for web text and for an\nundelivered quote). When every payload field is unset this is just the quote\n(cost), fetched later via the Contents endpoint (a Tako card URL ->\nChartConfig -> data; any other URL -> page text).");
export type ResultContent = z.infer<typeof ResultContent>;

export const RunSummaryEvent = z.object({ "kind": z.literal("run_summary").default("run_summary"), "status": z.lazy(() => AgentRunStatus), "created_at": z.string(), "completed_at": z.union([z.string(), z.null()]).optional(), "error": z.union([z.lazy(() => ErrorObject), z.null()]).optional(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional() }).describe("Terminal run metadata, emitted once immediately before stream_done. Mirrors\nthe GET-poll AgentRun fields the stream otherwise lacks; the result stays in the\nagent_result event. status/created_at/completed_at always present; error only on\nfailure; usage only on metered/PAYG runs (null otherwise). Sourced from the same\nprojection as the poll (run_projection.project_run), so\nagent_result + run_summary == the GET poll object. Synthesized by the stream\ngenerator — NOT a native block kind, so it is absent from PUBLIC_STREAM_KINDS.\n\nIt carries the SAME envelope `seq` as the stream_done it precedes (it has no\nseq of its own) and its SSE `id:` is suppressed, so it advances no resume\ncursor — identify it by `kind`, never by assuming `seq` is unique per frame.");
export type RunSummaryEvent = z.infer<typeof RunSummaryEvent>;

export const SearchAgentEffort = z.literal("medium").describe("Effort taxonomy for the Search Agent (POST /v1/agent/search/runs).\n\nLaunches single-tier: only MEDIUM is exposed (-> data_pipeline_medium_config).\nThe low/high data-pipeline configs exist but are deliberately not launched on\nthe public surface (S2 design / TAKO-3375, 2026-07-06). `effort` stays a\nrequest field for forward-compat + family parity with AnswerAgentEffort;\nlow/high 400 at validation. If tiers return, add the members here plus the\neffort pin + thread-context effort stamping.");
export type SearchAgentEffort = z.infer<typeof SearchAgentEffort>;

export const SearchAgentResult = z.object({ "answer": z.union([z.string(), z.null()]).optional(), "cards": z.array(z.lazy(() => TakoCard)).optional(), "citations": z.array(z.lazy(() => AgentAnswerCitation)).optional(), "metadata": z.union([z.lazy(() => AgentAnswerMetadata), z.null()]).optional(), "structured_output": z.union([z.record(z.string(), z.any()), z.null()]).describe("Caller-shaped structured output (present iff the request carried output_schema and status is not 'failed'). Dataset slots contain a TakoDataset envelope of exact retrieved rows, or null when honestly unfilled.").optional(), "structured_output_status": z.union([z.lazy(() => StructuredOutputStatus), z.null()]).describe("complete | partial | failed. Present when output_schema was supplied and the run reached finalize. May be absent if the whole run failed or timed out before finalize — the run-level status + error convey that, and the echoed request.output_schema still identifies it as a structured run.").optional(), "structured_output_citations": z.union([z.record(z.string(), z.array(z.number().int())), z.null()]).describe("Best-effort field-path -> citation-index map joining the top-level citations registry (same [n] index space as the answer). Absent when status is 'failed'.").optional(), "unfilled_fields": z.union([z.array(z.string()), z.null()]).describe("Dot-separated paths of honestly-unfilled dataset slots; present iff status is 'partial'.").optional(), "structured_output_error": z.union([z.lazy(() => ErrorObject), z.null()]).describe("Why structured output failed; present iff status is 'failed'.").optional(), "request_id": z.union([z.string(), z.null()]).optional() }).describe("Final search-agent output. answer is markdown prose with [n] citation\nmarkers; cards reuse the sibling TakoCard; citations is the unified\ntop-level registry (data + web, S1 §5.2) — there is no web_results field;\nmetadata carries definitions/assumptions/methodology (citations lifted out).\nstructured_output_* fields carry the caller-shaped output_schema result\n(S3 §5.1) — present iff the request supplied output_schema; see each\nfield's description for the exact presence matrix.");
export type SearchAgentResult = z.infer<typeof SearchAgentResult>;

export const SearchAgentResultEvent = z.object({ "kind": z.literal("agent_result").default("agent_result"), "id": z.string(), "data": z.lazy(() => SearchAgentResult) });
export type SearchAgentResultEvent = z.infer<typeof SearchAgentResultEvent>;

export const SearchAgentRun = z.object({ "run_id": z.string(), "object": z.literal("agent.search.run").default("agent.search.run"), "thread_id": z.union([z.string(), z.null()]).optional(), "status": z.lazy(() => AgentRunStatus), "created_at": z.string(), "completed_at": z.union([z.string(), z.null()]).optional(), "result": z.union([z.lazy(() => SearchAgentResult), z.null()]).optional(), "error": z.union([z.lazy(() => ErrorObject), z.null()]).optional(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional(), "request": z.union([z.lazy(() => SearchAgentRunRequest), z.null()]).optional() }).describe("The search-agent run resource returned by dispatch (202) and poll (GET).");
export type SearchAgentRun = z.infer<typeof SearchAgentRun>;

export const SearchAgentRunList = z.object({ "object": z.literal("list").default("list"), "data": z.array(z.lazy(() => SearchAgentRunSummary)), "has_more": z.boolean().default(false), "next_cursor": z.union([z.string(), z.null()]).optional() }).describe("OpenAI/Exa-style list envelope for GET /v1/agent/search/runs (TAKO-3384).");
export type SearchAgentRunList = z.infer<typeof SearchAgentRunList>;

export const SearchAgentRunRequest = z.object({ "query": z.string().describe("Natural-language data-retrieval request for the search agent."), "thread_id": z.union([z.string().uuid(), z.null()]).describe("Existing thread to continue (follow-up). Omit to start a new thread.").optional(), "effort": z.lazy(() => SearchAgentEffort).describe("Search-agent effort. Only 'medium' is currently supported.").default("medium"), "source_indexes": z.array(z.enum(["data","web"])).describe("Which sources the agent may use: 'data' (curated knowledge) and/or 'web' (open-web search). Defaults to ['data', 'web']. The legacy value 'tako' is accepted as a synonym for 'data'.").optional(), "cards": z.boolean().describe("Whether the agent may build visualization cards. Default true and permissive: true means the agent MAY build cards, not that it must (a completed run with no cards is legitimate). false suppresses card building entirely.").default(true), "output_schema": z.union([z.record(z.string(), z.any()), z.null()]).describe("JSON Schema for structured output. Synthesized fields are written by the agent; dataset slots (marked with x-tako-dataset: true) are filled with exact retrieved rows as a TakoDataset. Supported subset: object/array/string/number/integer/boolean types, enum, required, description; caps: 16KB, depth 5, 64 properties, 4 dataset slots. Violations return 400 output_schema_invalid.").optional(), "locale": z.string().describe("BCP-47 locale. Drives the language of the agent's answer and the locale used when rendering card preview images. Defaults to en-US.").default("en-US"), "timezone": z.union([z.string(), z.null()]).describe("IANA timezone (e.g. 'America/New_York') used to render dates/times in card preview images. Does not affect the returned data.").optional(), "output_settings": z.union([z.lazy(() => AgentOutputSettings), z.null()]).describe("Settings controlling the response/rendering.").optional() }).describe("Request body for POST /v1/agent/search/runs.");
export type SearchAgentRunRequest = z.infer<typeof SearchAgentRunRequest>;

export const SearchAgentRunSummary = z.object({ "run_id": z.string(), "status": z.lazy(() => AgentRunStatus), "created_at": z.string(), "completed_at": z.union([z.string(), z.null()]).optional(), "thread_id": z.union([z.string(), z.null()]).optional(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional(), "object": z.literal("agent.search.run").default("agent.search.run") });
export type SearchAgentRunSummary = z.infer<typeof SearchAgentRunSummary>;

export const SearchAgentStreamEnvelope = z.object({ "seq": z.number().int().gte(0), "run_id": z.string(), "thread_id": z.union([z.string(), z.null()]).optional(), "category": z.lazy(() => StreamCategory), "block": z.any().superRefine((x, ctx) => {
    const schemas = [z.lazy(() => ToolCallEvent), z.lazy(() => ToolResultEvent), z.lazy(() => ToolErrorEvent), z.lazy(() => ToolRetryEvent), z.lazy(() => StatusEvent), z.lazy(() => SubagentEvent), z.lazy(() => ReasoningEvent), z.lazy(() => TextEvent), z.lazy(() => DataPipelineAnswerEvent), z.lazy(() => SearchAgentResultEvent), z.lazy(() => RunSummaryEvent), z.lazy(() => HeartbeatEvent), z.lazy(() => StreamResetEvent), z.lazy(() => StreamDoneEvent)];
    const { errors, failed } = schemas.reduce<{
      errors: z.core.$ZodIssue[];
      failed: number;
    }>(
      ({ errors, failed }, schema) =>
        ((result) =>
          result.error
            ? {
                errors: [...errors, ...result.error.issues],
                failed: failed + 1,
              }
            : { errors, failed })(
          schema.safeParse(x),
        ),
      { errors: [], failed: 0 },
    );
    const passed = schemas.length - failed;
    if (passed !== 1) {
      ctx.addIssue(errors.length ? {
        path: [],
        code: "invalid_union",
        errors: [errors],
        message: "Invalid input: Should pass single schema. Passed " + passed,
      } : {
        path: [],
        code: "custom",
        errors: [errors],
        message: "Invalid input: Should pass single schema. Passed " + passed,
      });
    }
  }) }).describe("Public SSE envelope for the Search Agent run stream. Identical wire shape\nto AgentStreamEnvelope; the only difference is the terminal agent_result\nblock carries SearchAgentResult (unified top-level citations, no\nweb_results) — so the SSE terminal matches the GET poll projection.");
export type SearchAgentStreamEnvelope = z.infer<typeof SearchAgentStreamEnvelope>;

export const SearchEffortLevel = z.enum(["fast","instant","deep"]).describe("Public effort taxonomy for the new endpoints. FAST is the default. INSTANT\nserves cached embeds without re-running data retrieval and is available in all\nenvironments. DEEP widens TAKO retrieval and adds an LLM rerank for higher-quality results\n(slower; billed at a premium tier). The generated OpenAPI/SDK advertises\nexactly these members, so we add values only as the pipeline gains support.");
export type SearchEffortLevel = z.infer<typeof SearchEffortLevel>;

export const SearchRequest = z.object({ "query": z.string().describe("Natural language search query."), "effort": z.lazy(() => SearchEffortLevel).describe("Search effort level: 'fast' (default), 'instant', or 'deep'.").default("fast"), "sources": z.lazy(() => Sources).describe("Per-source settings. An index is searched iff its key is present; defaults to {data:{}, web:{}} (data + web, count 5 each). The legacy key 'tako' is accepted as a synonym for 'data'.").optional(), "country_code": z.string().describe("ISO 3166-1 alpha-2 country code for localization.").default("US"), "locale": z.string().describe("BCP-47 locale tag for language/formatting.").default("en-US"), "timezone": z.union([z.string(), z.null()]).describe("IANA timezone (e.g. 'America/New_York').").optional(), "output_settings": z.union([z.lazy(() => OutputSettings), z.null()]).describe("Settings controlling the response shape.").optional() }).strict();
export type SearchRequest = z.infer<typeof SearchRequest>;

export const SearchResponse = z.object({ "cards": z.array(z.lazy(() => TakoCard)).optional(), "web_results": z.array(z.lazy(() => WebResult)).optional(), "request_id": z.string(), "usage": z.union([z.lazy(() => Usage), z.null()]).optional() });
export type SearchResponse = z.infer<typeof SearchResponse>;

export const SourceSettings = z.object({ "count": z.number().int().gte(1).lte(20).describe("Maximum number of results to return for this source. 1-20.").default(5), "include_contents": z.boolean().describe("Inline this source's underlying data directly in the response (serialized card data — see content_format — for the Tako data source; extracted text for web results).").default(false) }).strict();
export type SourceSettings = z.infer<typeof SourceSettings>;

export const Sources = z.object({ "data": z.union([z.lazy(() => DataSourceSettings), z.null()]).describe("Tako data source (curated knowledge). Searched iff present. The legacy key 'tako' is accepted as a synonym.").optional(), "web": z.union([z.lazy(() => SourceSettings), z.null()]).describe("Web source. Searched iff present.").optional() }).strict().describe("Per-source settings. An index is searched iff its field is present.\n\nThe Tako data source is named `data`. The legacy key `tako` is still\naccepted as a synonym (mapped to `data` before validation).");
export type Sources = z.infer<typeof Sources>;

export const StatusEvent = z.object({ "kind": z.literal("status").default("status"), "message": z.string(), "parent_id": z.union([z.string(), z.null()]).optional() });
export type StatusEvent = z.infer<typeof StatusEvent>;

export const StreamCategory = z.enum(["content","activity","control"]);
export type StreamCategory = z.infer<typeof StreamCategory>;

export const StreamDoneEvent = z.object({ "kind": z.literal("stream_done").default("stream_done") });
export type StreamDoneEvent = z.infer<typeof StreamDoneEvent>;

export const StreamResetEvent = z.object({ "kind": z.literal("stream_reset").default("stream_reset") });
export type StreamResetEvent = z.infer<typeof StreamResetEvent>;

export const StructuredOutputStatus = z.enum(["complete","partial","failed"]).describe("Terminal status of the structured-output channel (S1 contract section 12).");
export type StructuredOutputStatus = z.infer<typeof StructuredOutputStatus>;

export const SubagentEvent = z.object({ "kind": z.literal("subagent").default("subagent"), "agent_id": z.string(), "subagent_type": z.string(), "parent_id": z.union([z.string(), z.null()]).optional(), "event": z.enum(["dispatch","complete"]) });
export type SubagentEvent = z.infer<typeof SubagentEvent>;

export const TakoCard = z.object({ "card_id": z.union([z.string(), z.null()]).optional(), "title": z.union([z.string(), z.null()]).optional(), "description": z.union([z.string(), z.null()]).optional(), "semantic_description": z.union([z.string(), z.null()]).optional(), "webpage_url": z.union([z.string(), z.null()]).optional(), "image_url": z.union([z.string(), z.null()]).optional(), "embed_url": z.union([z.string(), z.null()]).optional(), "sources": z.union([z.array(z.lazy(() => TakoCardSource)), z.null()]).optional(), "methodologies": z.union([z.array(z.lazy(() => KnowledgeCardMethodology)), z.null()]).optional(), "source_indexes": z.union([z.array(z.lazy(() => TakoSourceIndex)), z.null()]).optional(), "card_type": z.union([z.string(), z.null()]).optional(), "relevance": z.union([z.lazy(() => KnowledgeCardRelevance), z.null()]).optional(), "content": z.union([z.lazy(() => ResultContent), z.null()]).optional(), "relevance_score": z.union([z.number(), z.null()]).describe("Numeric relevance of this card to the query on a 1.0-5.0 scale (5.0 = exact match; higher is more relevant). Only populated for entitled accounts; null otherwise.").optional(), "nodes": z.union([z.array(z.lazy(() => TakoCardNode)), z.null()]).describe("Graph nodes (entities and metrics) this card was built from, returned by default. Absent for web-only cards or when node resolution was unavailable. Use each id with /beta/graph/node/{id} for full detail (aliases, subtype), or pass ids in sources.data.node_ids to pin these nodes in future searches.").optional() }).describe("A Tako knowledge card on the new search/answer surface. Mirrors the\nlegacy KnowledgeCard minus data_url / visualization_data / ideal_viz_decisions,\nplus a `content` download descriptor.");
export type TakoCard = z.infer<typeof TakoCard>;

export const TakoCardNode = z.object({ "id": z.string().describe("Opaque, human-friendly public id (<name-slug>-<token>)."), "type": z.lazy(() => GraphNodeType), "name": z.string(), "description": z.union([z.string(), z.null()]).optional() }).describe("Slim graph node for the search/answer card surface (TakoCard.nodes) and\nits internal carrier. Deliberately narrower than GraphNode: no `aliases`\n(bulky, and the card surface never needs them) and no `subtype` (the search\nhydration path resolves ids in one batch KG fetch and does not pay the\nsecond EntityClassResolver round-trip that subtype would require). Callers\nthat need the full node — aliases, subtype — resolve the id via\n/beta/graph/node/{id}.");
export type TakoCardNode = z.infer<typeof TakoCardNode>;

export const TakoCardSource = z.object({ "source_name": z.union([z.string(), z.null()]).describe("The name of the source").optional(), "source_description": z.union([z.string(), z.null()]).describe("The description of the source").optional(), "source_index": z.lazy(() => TakoSourceIndex).describe("The index of the source"), "url": z.union([z.string(), z.null()]).describe("The URL of the source").optional(), "source_text": z.union([z.string(), z.null()]).describe("Raw excerpt(s) retrieved from the source page — the unmodified web content the answer was grounded in. Populated for WEB sources; null for DATA sources.").optional() }).describe("A source backing a TakoCard, on the SDK surfaces. Mirrors the legacy\nKnowledgeCardSource minus the segment/private-index variants (unreachable on\nthese surfaces) and using the {data, web} TakoSourceIndex taxonomy.");
export type TakoCardSource = z.infer<typeof TakoCardSource>;

export const TakoDatasetColumn = z.object({ "name": z.string(), "type": z.lazy(() => TakoDatasetColumnType) }).describe("Typed header entry; `type` is the JSON-facing column type.");
export type TakoDatasetColumn = z.infer<typeof TakoDatasetColumn>;

export const TakoDatasetColumnType = z.enum(["string","number","boolean","date","datetime"]).describe("Logical column type declared in a TakoDataset header. Temporal cells are\nISO-8601 strings; date vs datetime is decided per column (a temporal column\nwhose non-null values are all tz-naive midnights declares 'date').");
export type TakoDatasetColumnType = z.infer<typeof TakoDatasetColumnType>;

export const TakoDatasetSource = z.object({ "name": z.string(), "index": z.enum(["data","web"]).default("data") }).describe("Per-dataset provenance entry. `index` is the SOURCE index (\"data\" for\nevery v1 splice — web never splices, S1 contract section 7), not a citation\ndisplay number. Mirrors the public TakoSourceIndex taxonomy as a plain\nLiteral; S7 revisits naming when the component goes public.");
export type TakoDatasetSource = z.infer<typeof TakoDatasetSource>;

export const TakoSourceIndex = z.enum(["data","web"]).describe("Public source taxonomy for the SDK card surfaces (v3 search, v1 answer,\nagent). Symmetric with the request taxonomy {data, web}. Distinct from the\ninternal/legacy CardSourceIndex used by the internal /v1/knowledge_search\npath, which carries additional internal-only index names.");
export type TakoSourceIndex = z.infer<typeof TakoSourceIndex>;

export const TextEvent = z.object({ "kind": z.literal("text").default("text"), "id": z.string(), "delta": z.string(), "done": z.boolean().default(false) });
export type TextEvent = z.infer<typeof TextEvent>;

export const ThinVizCard = z.object({ "card_id": z.union([z.string(), z.null()]).describe("Public ID of the created card.").optional(), "title": z.union([z.string(), z.null()]).describe("Card title.").optional(), "description": z.union([z.string(), z.null()]).describe("Card description.").optional(), "webpage_url": z.union([z.string(), z.null()]).describe("Hosted page URL for the card.").optional(), "image_url": z.union([z.string(), z.null()]).describe("Static preview image URL for the card.").optional(), "embed_url": z.union([z.string(), z.null()]).describe("Embeddable URL for the card.").optional(), "card_type": z.union([z.string(), z.null()]).describe("The card/chart type (e.g. 'bar').").optional(), "visualization_data": z.union([z.record(z.string(), z.any()), z.null()]).describe("Inline chart config + data for rendering the card.").optional(), "embed_mode": z.union([z.enum(["post","postmessage"]), z.null()]).describe("How the embed is delivered: 'postmessage' for postMessage embeds, 'post' otherwise.").optional() }).describe("Response for POST /api/v1/thin_viz/create — a created visualization card.\n\nDistinct from KnowledgeCard: thin_viz builds a self-contained chart from a\ncaller-supplied component schema, so it never carries retrieval provenance\n(sources / source_indexes) or downloadable raw data. The card is rendered via\n`embed_url` and previewed via `image_url`; `visualization_data` carries the\ninline chart config + data.\n\nDocuments the populated subset of the response. The view emits a full\nKnowledgeCard dump, so the wire payload also includes the remaining\nKnowledgeCard fields (sources, source_indexes, methodologies, data_url, etc.)\nas null; those are intentionally undocumented here (always null for thin_viz)\nso the public schema does not pull in the internal CardSourceIndex taxonomy.");
export type ThinVizCard = z.infer<typeof ThinVizCard>;

export const ToolCallEvent = z.object({ "kind": z.literal("tool_call").default("tool_call"), "id": z.string(), "tool": z.string(), "status_message": z.union([z.string(), z.null()]).optional(), "parent_id": z.union([z.string(), z.null()]).optional(), "done": z.boolean().default(false) });
export type ToolCallEvent = z.infer<typeof ToolCallEvent>;

export const ToolErrorEvent = z.object({ "kind": z.literal("tool_error").default("tool_error"), "id": z.string(), "tool": z.string(), "error": z.string(), "parent_id": z.union([z.string(), z.null()]).optional() });
export type ToolErrorEvent = z.infer<typeof ToolErrorEvent>;

export const ToolResultEvent = z.object({ "kind": z.literal("tool_result").default("tool_result"), "id": z.string(), "tool": z.string(), "elapsed_ms": z.number().int().default(0), "link": z.union([z.string(), z.null()]).optional(), "parent_id": z.union([z.string(), z.null()]).optional() });
export type ToolResultEvent = z.infer<typeof ToolResultEvent>;

export const ToolRetryEvent = z.object({ "kind": z.literal("tool_retry").default("tool_retry"), "id": z.string(), "tool": z.string(), "error": z.string(), "elapsed_ms": z.number().int().default(0), "parent_id": z.union([z.string(), z.null()]).optional() });
export type ToolRetryEvent = z.infer<typeof ToolRetryEvent>;

export const Usage = z.object({ "total_cost_usd": z.number(), "compute": z.union([z.lazy(() => UsageCompute), z.null()]).optional(), "data": z.union([z.lazy(() => UsageData), z.null()]).optional() }).describe("Cost-plus usage for one metered request. `total_cost_usd` is always present\n(the total quoted charge). `compute` / `data` are the additive breakdown and\nappear only where they apply. See module docstring for the quote-vs-drawdown\ncaveat and the total == compute + data invariant.");
export type Usage = z.infer<typeof Usage>;

export const UsageCompute = z.object({ "cost_usd": z.number() }).describe("Cost of running the operation (agent COGS x multiplier, or the flat\nsearch/answer per-request rate). Absent on surfaces with no compute step\n(contents).");
export type UsageCompute = z.infer<typeof UsageCompute>;

export const UsageData = z.object({ "cost_usd": z.number(), "datasets": z.number().int() }).describe("Cost + quantity of inline data delivered in the response (agent per-dataset\nsurcharge, search/answer include_contents charge, or the contents per-item\ncost). `datasets` is the count of billed data units. Absent when the surface\ndid not / cannot emit inline data (e.g. the answer agent).");
export type UsageData = z.infer<typeof UsageData>;

export const WebResult = z.object({ "title": z.string().describe("Title of the web page."), "url": z.string().describe("URL of the web page."), "snippet": z.union([z.string(), z.null()]).describe("Excerpt(s) from the page that matched the query.").optional(), "source_name": z.union([z.string(), z.null()]).describe("Publisher / domain name, when extractable from the URL.").optional(), "publish_date": z.union([z.string(), z.null()]).describe("Publication date of the page, when available.").optional(), "content": z.union([z.lazy(() => ResultContent), z.null()]).describe("Downloadable content descriptor for this result, fetched via the Contents endpoint. Web results are always downloadable as text. None for callers that do not populate it.").optional(), "citation_number": z.union([z.number().int(), z.null()]).describe("1-based citation number that the answer's inline [N] markers reference. Set only when the answer inline-cites this result (the Agent API); None on raw-retrieval surfaces.").optional() }).describe("A single raw web search result returned by the WEB source index.\n\nDistinct from `KnowledgeCardSource` (a citation inside a synthesized\nanswer) and `KnowledgeCard` (a Tako visualization). Web results are\nraw retrieval output — title, URL, optional snippet — independent of\nany LLM synthesis that may also happen over them.");
export type WebResult = z.infer<typeof WebResult>;
